// ===== 2ГИС: отзывы из Apify → дайджест за неделю =====
const DAYS = 7, STALE_DAYS = 8;
const runsResp = (() => { try { return $('Запуски Apify').first().json || {}; } catch (e) { return {}; } })();
const picked = (() => { try { return $('Выбрать запуски').all().map(i => i.json); } catch (e) { return []; } })();
const newest = picked.map(r => r.finishedAt).filter(Boolean).sort().slice(-1)[0] || null;
const run = { error: runsResp.error, data: newest ? { finishedAt: newest } : null };
const rawItems = $input.all().map(i => i.json);

const MONTHS = { 'января':0,'февраля':1,'марта':2,'апреля':3,'мая':4,'июня':5,'июля':6,'августа':7,'сентября':8,'октября':9,'ноября':10,'декабря':11 };
const now = new Date(); const T0 = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const fmt = ms => { const d = new Date(ms); return `${String(d.getUTCDate()).padStart(2,'0')}.${String(d.getUTCMonth()+1).padStart(2,'0')}.${d.getUTCFullYear()}`; };
function parseDate(v) {                       // → UTC-полночь дня или null
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') { const ms = v > 1e11 ? v : v * 1000; const d = new Date(ms); return isNaN(d) ? null : Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()); }
  const s = String(v).trim().toLowerCase(); let m;
  if (/^\d{9,13}$/.test(s)) return parseDate(Number(s));
  if ((m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s))) return Date.UTC(+m[1], +m[2]-1, +m[3]);
  if ((m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})/.exec(s))) return Date.UTC(+m[3], +m[2]-1, +m[1]);
  if ((m = /(\d{1,2})\s+([а-яё]+)\s*(\d{4})?/.exec(s)) && MONTHS[m[2]] !== undefined) {
    let y = m[3] ? +m[3] : now.getUTCFullYear(); let d = Date.UTC(y, MONTHS[m[2]], +m[1]);
    if (!m[3] && d > T0 + 86400000) d = Date.UTC(y - 1, MONTHS[m[2]], +m[1]); return d;
  }
  const d = new Date(s); return isNaN(d) ? null : Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
}
// первое непустое значение по списку возможных названий поля (в т.ч. вложенных через точку)
const pick = (o, keys) => { for (const k of keys) { let v = o; for (const p of k.split('.')) v = v == null ? undefined : v[p]; if (v !== undefined && v !== null && v !== '') return v; } return null; };
const str = v => v === null ? '' : (typeof v === 'object' ? String(v.name ?? v.title ?? v.text ?? '') : String(v)).trim();
const numv = v => { if (v === null) return null; if (typeof v === 'object') v = v.value ?? v.rating ?? v.score; const n = parseFloat(String(v).replace(',', '.')); return isNaN(n) ? null : n; };

const K = {
  club:   ['placeName','place.name','placeTitle','place.title','branchName','organizationName','orgName','firmName','businessName','companyName','object.name','org.name'],
  clubId: ['placeId','branchId','firmId','orgId','objectId','place.id'],
  text:   ['reviewText','text','comment','content','review','body','message'],
  rating: ['rating','reviewRating','stars','score','rate'],
  author: ['authorName','author.name','author','userName','user.name','reviewerName','reviewer.name','user'],
  date:   ['createdAt','dateCreated','date','reviewDate','publishedAt','published','created','dateEdited','timestamp','time'],
  id:     ['reviewId','id','review_id'],
};

// ---- диагностика источника ----
const problems = []; let status = 'ok';
if (run.error) problems.push(`Apify (статус запуска): ${str(run.error.message || run.error.type || JSON.stringify(run.error)).slice(0, 200)}`);
const finished = run.data && run.data.finishedAt ? new Date(run.data.finishedAt) : null;
const ageDays = finished ? (Date.now() - finished.getTime()) / 86400000 : null;
if (finished && ageDays > STALE_DAYS) { status = 'stale'; }
if (!finished && !run.error) problems.push('Apify не вернул дату последнего успешного запуска');
const errItem = rawItems.find(r => r && r.error);
if (errItem) problems.push(`Apify (датасет): ${str(errItem.error.message || errItem.error.type || JSON.stringify(errItem.error)).slice(0, 200)}`);
const items = rawItems.filter(r => r && !r.error && typeof r === 'object' && Object.keys(r).length);

// ---- разбор ----
const cutoff = T0 - DAYS * 86400000;
const parsed = [];
for (const r of items) {
  const rt = str(pick(r, ['recordType','type']));
  if (rt && !/review|отзыв/i.test(rt)) continue;                 // строки о самом месте — пропускаем
  const text = str(pick(r, K.text)), rating = numv(pick(r, K.rating)), dateRaw = pick(r, K.date), date = parseDate(dateRaw);
  if (!text && rating === null && date === null) continue;       // пустая строка
  const clubName = str(pick(r, K.club)) || (pick(r, K.clubId) ? `Клуб (ID ${str(pick(r, K.clubId))})` : 'Неизвестный клуб');
  parsed.push({ id: str(pick(r, K.id)), club: clubName, author: str(pick(r, K.author)) || 'Аноним', text, rating, date, dateRaw });
}
const undated = parsed.filter(r => r.date === null).length;
const seen = new Set();
const fresh = parsed.filter(r => r.date !== null && r.date >= cutoff && r.date <= T0 + 86400000)
  .filter(r => { const k = (r.id ? r.club + '|' + r.id : r.club + '|' + r.author + '|' + r.date + '|' + r.text); if (seen.has(k)) return false; seen.add(k); return true; })
  .sort((a, b) => b.date - a.date);

const diagLines = [
  `Последний успешный запуск Apify: ${finished ? fmt(finished.getTime()) + ` (${ageDays.toFixed(1)} дн. назад)` : 'неизвестно'}`,
  `Строк в датасете: ${rawItems.length}, отзывов распознано: ${parsed.length}, за ${DAYS} дн.: ${fresh.length}${undated ? `, без распознанной даты: ${undated}` : ''}`,
];
const clubsAll = [...new Set(parsed.map(r => r.club))];
diagLines.push(`Запусков Apify учтено: ${picked.filter(r => r.datasetId).length}, клубов в данных: ${clubsAll.length}${clubsAll.length ? ' (' + clubsAll.join(', ') + ')' : ''}`);
if (items[0]) diagLines.push('Поля первой строки: ' + Object.keys(items[0]).slice(0, 25).join(', '));

let text = '', digest = '', total = fresh.length;
if (status === 'stale') {
  text = `🚨 Дайджест отзывов 2ГИС не отправлен: данные в Apify устарели.\nПоследний успешный запуск парсера был ${fmt(finished.getTime())} (${Math.round(ageDays)} дн. назад) — новых отзывов он не собирал.\n\nПроверьте расписание запуска актора в Apify (Schedules) и его последний запуск.\n\n` + diagLines.join('\n');
} else if (problems.length && !items.length) {
  status = 'alert';
  text = '🚨 Дайджест отзывов 2ГИС: не удалось получить данные из Apify.\n' + problems.join('\n') + '\n\n' + diagLines.join('\n') + '\n\nПроверьте токен Apify и что у актора есть успешный запуск.';
} else if (!items.length) {
  status = 'alert';
  text = '🚨 Дайджест отзывов 2ГИС: датасет последнего запуска пуст (это не значит, что отзывов нет).\n\n' + diagLines.join('\n');
} else if (!parsed.length || (undated === parsed.length)) {
  status = 'alert';
  text = '🚨 Дайджест отзывов 2ГИС: не смог распознать поля в данных Apify (изменился формат актора?).\n\n' + diagLines.join('\n') + '\n\nПришлите это сообщение — подправлю разбор.';
} else if (!fresh.length) {
  status = 'empty';
  text = `📊 Еженедельный дайджест отзывов (2ГИС)\n📅 за последние ${DAYS} дней | г. Октябрьский\n\nЗа последнюю неделю новых отзывов не появилось.`;
} else {
  const tone = r => r === null ? '➖' : r >= 4 ? '✅' : r === 3 ? '➖' : '⚠️';
  const num = n => n <= 9 ? `${n}️⃣` : `${n}.`;
  const byClub = {}; fresh.forEach(r => (byClub[r.club] = byClub[r.club] || []).push(r));
  const L = ['📊 Еженедельный дайджест отзывов (2ГИС)', `📅 Свежие отзывы за последние ${DAYS} дней | г. Октябрьский`];
  let pos = 0, neg = 0, neu = 0, sum = 0, cnt = 0;
  for (const [club, rs] of Object.entries(byClub).sort((a, b) => b[1].length - a[1].length)) {
    L.push('', '─────────────', `🏢 Клуб: ${club}`, `📝 Новых отзывов: ${rs.length}`);
    rs.forEach((r, k) => {
      const t = tone(r.rating); if (t === '✅') pos++; else if (t === '⚠️') neg++; else neu++;
      if (r.rating !== null) { sum += r.rating; cnt++; }
      L.push('', `${num(k + 1)} 👤 ${r.author} | 📅 ${fmt(r.date)} | ⭐ ${r.rating ?? '—'}/5`);
      L.push(r.text ? `💬 "${r.text}"` : '💬 (без текста, только оценка)', t);
    });
  }
  // сравнение с прошлой неделей (работает при запуске по расписанию — память воркфлоу)
  const sd = $getWorkflowStaticData('global'); const prevTotal = sd.prevTotal;
  const cmp = (prevTotal !== undefined && prevTotal !== null) ? ` (прошлая неделя: ${prevTotal})` : '';
  sd.prevTotal = total;
  L.push('', '─────────────', '📌 Общий итог по неделе:', `Всего новых отзывов: ${total}${cmp}`, `Позитивных: ${pos} ✅`, `Негативных: ${neg} ⚠️`, `Нейтральных: ${neu} ➖`);
  if (cnt) L.push(`Средняя оценка: ${(sum / cnt).toFixed(1)} ⭐`);
  L.push(`🏢 Клубов с отзывами за неделю: ${Object.keys(byClub).length} из ${clubsAll.length} в данных Apify`);
  if (ageDays !== null && ageDays > 3) L.push('', `ℹ️ Данные Apify собраны ${fmt(finished.getTime())}`);
  digest = L.join('\n');
}
const forAI = fresh.map(r => ({ club: r.club, rating: r.rating, text: (r.text || '').slice(0, 400) }));
return [{ json: { status: status === 'ok' ? 'ok' : status, text, digest, total, reviews: forAI, diag: diagLines } }];

// Склейка дайджеста с блоком тем/вывода от ИИ и деление на сообщения ≤ 4000 символов
const base = $('Разбор отзывов').first().json;
let ai = String($input.first().json.output || '').replace(/\*\*/g, '').trim();
let full = base.digest + (ai ? '\n\n─────────────\n' + ai : '');
const LIM = 3900, parts = []; let cur = '';
for (const line of full.split('\n')) {
  if ((cur + '\n' + line).length > LIM) { parts.push(cur); cur = line; } else cur = cur ? cur + '\n' + line : line;
}
if (cur) parts.push(cur);
return parts.map(t => ({ json: { text: t } }));

// Берём все успешные запуски актора за последние 8 дней (каждый мог собирать свой клуб)
const items = ($input.first().json.data && $input.first().json.data.items) || [];
const WINDOW = 8 * 86400000;
const recent = items.filter(r => r.finishedAt && Date.now() - new Date(r.finishedAt).getTime() <= WINDOW && r.defaultDatasetId);
// если свежих нет — берём самый новый, чтобы дальше сработала проверка «данные устарели»
const use = (recent.length ? recent : items.slice(0, 1)).slice(0, 30);
if (!use.length) return [{ json: { datasetId: '', finishedAt: null } }];
const seen = new Set();
return use.filter(r => !seen.has(r.defaultDatasetId) && seen.add(r.defaultDatasetId))
  .map(r => ({ json: { datasetId: r.defaultDatasetId, finishedAt: r.finishedAt, runId: r.id } }));
